  --ui-color-on-primary: hsla(0, 0%, 100%, 1);
  --ui-color-on-destructive: hsla(0, 0%, 100%, 1);
  --ui-color-on-success: hsla(0, 0%, 0%, 1);
  --ui-color-on-warning: hsla(0, 0%, 0%, 1);
  --ui-color-on-info: hsla(0, 0%, 0%, 1);
  --ui-color-on-tint-scrim: hsla(0, 0%, 0%, 0.40);
  --ui-color-interactive-hover: hsla(200, 7%, 91%, 0.06);
  --ui-color-interactive-press: hsla(200, 7%, 91%, 0.12);
  --ui-color-border: hsla(210, 7%, 18%, 1);
  --ui-color-outline: hsla(210, 8%, 28%, 1);
  --ui-color-focus-ring: hsla(204, 88%, 53%, 0.70);
  --ui-color-tab-icon-default: hsla(210, 11%, 60%, 1);
  --ui-color-tab-icon-selected: hsla(200, 7%, 91%, 1);
  --ui-color-destructive: hsla(356, 91%, 66%, 1);
  --ui-color-destructive-active: hsla(356, 78%, 46%, 1);
  --ui-color-destructive-surface: hsla(356, 91%, 54%, 0.16);
  --ui-color-success: hsla(160, 100%, 36%, 1);
  --ui-color-success-surface: hsla(160, 100%, 36%, 0.16);
  --ui-color-warning: hsla(50, 100%, 50%, 1);
  --ui-color-warning-surface: hsla(50, 100%, 50%, 0.16);
  --ui-color-info: hsla(204, 88%, 53%, 1);
  --ui-color-info-surface: hsla(204, 88%, 53%, 0.14);
  --ui-color-disabled: hsla(210, 10%, 16%, 1);
  --ui-color-scrim: hsla(0, 0%, 0%, 0.72);
  --ui-color-shadow-color: hsla(0, 0%, 0%, 0.50);
  --ui-elevation-1: hsla(220, 12%, 10%, 1);
  --ui-elevation-2: hsla(220, 12%, 10%, 1);
  --ui-elevation-3: hsla(220, 12%, 10%, 1);
  --ui-elevation-4: hsla(220, 12%, 10%, 1);
  --ui-elevation-5: hsla(210, 10%, 14%, 1);
  --color-background: var(--ui-color-background);
  --color-surface: var(--ui-color-surface);
  --color-surface-sunken: var(--ui-color-surface-sunken);
  --color-surface-muted: var(--ui-color-surface-muted);
  --color-surface-elevated: var(--ui-color-surface-elevated);
  --color-surface-overlay: var(--ui-color-surface-overlay);
  --color-text: var(--ui-color-text);
  --color-text-secondary: var(--ui-color-text-secondary);
  --color-icon: var(--ui-color-icon);
  --color-tint: var(--ui-color-tint);
  --color-tint-hover: var(--ui-color-tint-hover);
  --color-tint-active: var(--ui-color-tint-active);
  --color-tint-subtle: var(--ui-color-tint-subtle);
  --color-tint-muted: var(--ui-color-tint-muted);
  --color-tint-highlight: var(--ui-color-tint-highlight);
  --color-on-primary: var(--ui-color-on-primary);
  --color-on-destructive: var(--ui-color-on-destructive);
  --color-on-success: var(--ui-color-on-success);
  --color-on-warning: var(--ui-color-on-warning);
  --color-on-info: var(--ui-color-on-info);
  --color-on-tint-scrim: var(--ui-color-on-tint-scrim);
  --color-interactive-hover: var(--ui-color-interactive-hover);
  --color-interactive-press: var(--ui-color-interactive-press);
  --color-border: var(--ui-color-border);
  --color-outline: var(--ui-color-outline);
  --color-focus-ring: var(--ui-color-focus-ring);
  --color-tab-icon-default: var(--ui-color-tab-icon-default);
  --color-tab-icon-selected: var(--ui-color-tab-icon-selected);
  --color-destructive: var(--ui-color-destructive);
  --color-destructive-active: var(--ui-color-destructive-active);
  --color-destructive-surface: var(--ui-color-destructive-surface);
  --color-success: var(--ui-color-success);
  --color-success-surface: var(--ui-color-success-surface);
  --color-warning: var(--ui-color-warning);
  --color-warning-surface: var(--ui-color-warning-surface);
  --color-info: var(--ui-color-info);
  --color-info-surface: var(--ui-color-info-surface);
  --color-disabled: var(--ui-color-disabled);
  --color-scrim: var(--ui-color-scrim);
  --color-shadow-color: var(--ui-color-shadow-color);
  --color-elevation-1: var(--ui-elevation-1);
  --color-elevation-2: var(--ui-elevation-2);
  --color-elevation-3: var(--ui-elevation-3);
  --color-elevation-4: var(--ui-elevation-4);
  --color-elevation-5: var(--ui-elevation-5);
  --ui-on-fg: var(--ui-color-text);
  --ui-on-fg-muted: var(--ui-color-text-secondary);
  --ui-on-icon: var(--ui-color-icon);
  color-scheme: dark;
